  public static Tokenrequest.X509MintRequest x509MintRequestFromBytes(byte[] data)
      throws ProtoException {
    if (data == null || data.length == 0) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "data is null or empty");
    }
    String dataStr = new String(data).trim();
    if (dataStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "empty data after trimming");
    }
    if (dataStr.startsWith("{") || dataStr.startsWith("[")) {
      try {
        return x509MintRequestFromJson(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains(":") && !dataStr.contains("=")) {
      try {
        return x509MintRequestFromYaml(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains("=")) {
      try {
        return x509MintRequestFromToml(dataStr);
      } catch (Exception e) {
        // Fall through to try binary
      }
    }
    try {
      return x509MintRequestFromBinary(data);
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to parse X509MintRequest: unsupported format or invalid data: " + e.getMessage(),
          e);
    }
  }

  public static Tokenrequest.X509MintRequest x509MintRequestFromJson(String json)
      throws ProtoException {
    if (json == null || json.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "json is null or empty");
    }
    try {
      Tokenrequest.X509MintRequest.Builder builder = Tokenrequest.X509MintRequest.newBuilder();
      Gson gson = new Gson();
      JsonObject obj = gson.fromJson(json, JsonObject.class);
      JsonElement audEl = obj.get("aud");
      if (audEl != null && !audEl.isJsonNull()) {
        if (audEl.isJsonPrimitive()) {
          builder.setAud(audEl.getAsString());
        }
      }
      JsonElement certRequestEl = null;
      if (certRequestEl == null) certRequestEl = obj.get("certRequest");
      if (certRequestEl == null) certRequestEl = obj.get("cert_request");
      if (certRequestEl != null && !certRequestEl.isJsonNull()) {
        if (certRequestEl.isJsonObject()) {
          try {
            builder.setCertRequest(
                com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.x509
                    .Helpers.x509CertRequestFromJson(certRequestEl.toString()));
          } catch (Exception e) {
          }
        }
      }
      JsonElement inputTokenEl = null;
      if (inputTokenEl == null) inputTokenEl = obj.get("inputToken");
      if (inputTokenEl == null) inputTokenEl = obj.get("input_token");
      if (inputTokenEl != null && !inputTokenEl.isJsonNull()) {
        if (inputTokenEl.isJsonPrimitive()) {
          builder.setInputToken(inputTokenEl.getAsString());
        }
      }
      return builder.build();
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          "Failed to parse X509MintRequest from JSON: " + e.getMessage(),
          e);
    }
  }

