  public static String x509MintRequestToYaml(Tokenrequest.X509MintRequest msg)
      throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "X509MintRequest is null");
    }
    try {
      String json = x509MintRequestToJson(msg);
      Gson gson = new Gson();
      Map<String, Object> map =
          gson.fromJson(
              json, new com.google.gson.reflect.TypeToken<Map<String, Object>>() {}.getType());
      Yaml yaml = new Yaml();
      return yaml.dump(map);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to serialize X509MintRequest to YAML: " + e.getMessage(),
          e);
    }
  }

  public static Tokenrequest.X509MintRequest x509MintRequestFromYaml(String yamlStr)
      throws ProtoException {
    if (yamlStr == null || yamlStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "yamlStr is null or empty");
    }
    try {
      Yaml yaml = new Yaml();
      @SuppressWarnings("unchecked")
      Map<String, Object> map = (Map<String, Object>) yaml.load(yamlStr);
      Gson gson = new Gson();
      String json = gson.toJson(map);
      return x509MintRequestFromJson(json);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to parse X509MintRequest from YAML: " + e.getMessage(),
          e);
    }
  }

  public static String x509MintRequestToToml(Tokenrequest.X509MintRequest msg)
      throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "X509MintRequest is null");
    }
    try {
      String json = x509MintRequestToJson(msg);
      Gson gson = new Gson();
      Map<String, Object> map =
          gson.fromJson(
              json, new com.google.gson.reflect.TypeToken<Map<String, Object>>() {}.getType());
      StringBuilder toml = new StringBuilder();
      if (map == null || map.isEmpty()) {
        return "# Empty X509MintRequest\n";
      }
      for (Map.Entry<String, Object> entry : map.entrySet()) {
        toml.append(entry.getKey()).append(" = ");
        if (entry.getValue() instanceof String) {
          toml.append("\"").append(entry.getValue()).append("\"");
        } else {
          toml.append(entry.getValue());
        }
        toml.append("\n");
      }
      return toml.toString();
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to serialize X509MintRequest to TOML: " + e.getMessage(),
          e);
    }
  }

  public static Tokenrequest.X509MintRequest x509MintRequestFromToml(String tomlStr)
      throws ProtoException {
    if (tomlStr == null || tomlStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "tomlStr is null or empty");
    }
    try {
      Toml toml = new Toml().read(tomlStr);
      Map<String, Object> map = toml.toMap();
      Gson gson = new Gson();
      String json = gson.toJson(map);
      return x509MintRequestFromJson(json);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to parse X509MintRequest from TOML: " + e.getMessage(),
          e);
    }
  }

  // ============ Validation ============
  public static void validateTokenMintRequest(Tokenrequest.TokenMintRequest msg)
      throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate aud (assert_min_length: 1)
    if (msg.getAud().length() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field aud must be at least 1 characters, got: %d", msg.getAud().length()));
    }
    // Validate aud (assert_max_length: 256)
    if (msg.getAud().length() > 256) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field aud must be at most 256 characters, got: %d", msg.getAud().length()));
    }
    // Validate exp (assert_ge: 0)
    if (msg.getExp() < 0L) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field exp must be >= 0, got: %s", msg.getExp()));
    }
    // Validate subject (assert_max_length: 256)
    if (msg.getSubject().length() > 256) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field subject must be at most 256 characters, got: %d", msg.getSubject().length()));
    }
  }

